19	package org.apache.hadoop.util;
20	
21	import org.apache.hadoop.io.compress.ZStandardCodec;
22	import org.apache.hadoop.io.erasurecode.ErasureCodeNative;
23	import org.apache.hadoop.conf.Configuration;
24	import org.apache.hadoop.crypto.OpensslCipher;
25	import org.apache.hadoop.io.compress.bzip2.Bzip2Factory;
26	import org.apache.hadoop.io.compress.zlib.ZlibFactory;
27	import org.apache.hadoop.classification.InterfaceAudience;
28	import org.apache.hadoop.classification.InterfaceStability;
29	import org.apache.hadoop.io.nativeio.NativeIO;
30	import org.slf4j.Logger;
31	import org.slf4j.LoggerFactory;
32	
33	import java.io.IOException;
34	
35	@InterfaceAudience.Private
36	@InterfaceStability.Unstable
37	public class NativeLibraryChecker {
38	  public static final Logger LOG =
39	      LoggerFactory.getLogger(NativeLibraryChecker.class);
40	
41	  /**
42	   * A tool to test native library availability, 
43	   */
44	  public static void main(String[] args) {
45	    String usage = "NativeLibraryChecker [-a|-h]\n"
46	        + "  -a  use -a to check all libraries are available\n"
47	        + "      by default just check hadoop library (and\n"
48	        + "      winutils.exe on Windows OS) is available\n"
49	        + "      exit with error code 1 if check failed\n"
50	        + "  -h  print this message\n";
51	    if (args.length > 1 ||
52	        (args.length == 1 &&
53	            !(args[0].equals("-a") || args[0].equals("-h")))) {
54	      System.err.println(usage);
55	      ExitUtil.terminate(1);
56	    }
57	    boolean checkAll = false;
58	    if (args.length == 1) {
59	      if (args[0].equals("-h")) {
60	        System.out.println(usage);
61	        return;
62	      }
63	      checkAll = true;
64	    }
65	    Configuration conf = new Configuration();
66	    boolean nativeHadoopLoaded = NativeCodeLoader.isNativeCodeLoaded();
67	    boolean zlibLoaded = false;
68	    boolean isalLoaded = false;
69	    boolean zStdLoaded = false;
70	    boolean pmdkLoaded = false;
71	    boolean bzip2Loaded = Bzip2Factory.isNativeBzip2Loaded(conf);
72	    boolean openSslLoaded = false;
73	    boolean winutilsExists = false;
74	
75	    String openSslDetail = "";
76	    String hadoopLibraryName = "";
77	    String zlibLibraryName = "";
78	    String isalDetail = "";
79	    String pmdkDetail = "";
80	    String zstdLibraryName = "";
81	    String bzip2LibraryName = "";
82	    String winutilsPath = null;
83	
84	    if (nativeHadoopLoaded) {
85	      hadoopLibraryName = NativeCodeLoader.getLibraryName();
86	      zlibLoaded = ZlibFactory.isNativeZlibLoaded(conf);
87	      if (zlibLoaded) {
88	        zlibLibraryName = ZlibFactory.getLibraryName();
89	      }
90	      zStdLoaded = NativeCodeLoader.buildSupportsZstd() &&
91	        ZStandardCodec.isNativeCodeLoaded();
92	      if (zStdLoaded && NativeCodeLoader.buildSupportsZstd()) {
93	        zstdLibraryName = ZStandardCodec.getLibraryName();
94	      }
95	
96	      isalDetail = ErasureCodeNative.getLoadingFailureReason();
97	      if (isalDetail != null) {
98	        isalLoaded = false;
99	      } else {
100	        isalDetail = ErasureCodeNative.getLibraryName();
101	        isalLoaded = true;
102	      }
103	
104	      pmdkDetail = NativeIO.POSIX.getPmdkSupportStateMessage();
105	      pmdkLoaded = NativeIO.POSIX.isPmdkAvailable();
106	      if (pmdkLoaded) {
107	        pmdkDetail = NativeIO.POSIX.Pmem.getPmdkLibPath();
108	      }
109	
110	      openSslDetail = OpensslCipher.getLoadingFailureReason();
111	      if (openSslDetail != null) {
112	        openSslLoaded = false;
113	      } else {
114	        openSslDetail = OpensslCipher.getLibraryName();
115	        openSslLoaded = true;
116	      }
117	
118	      if (bzip2Loaded) {
119	        bzip2LibraryName = Bzip2Factory.getLibraryName(conf);
120	      }
121	    }
122	
123	    if (Shell.WINDOWS) {
124	      // winutils.exe is required on Windows
125	      try {
126	        winutilsPath = Shell.getWinUtilsFile().getCanonicalPath();
127	        winutilsExists = true;
128	      } catch (IOException e) {
129	        LOG.debug("No Winutils: ", e);
130	        winutilsPath = e.getMessage();
131	        winutilsExists = false;
132	      }
133	      System.out.printf("winutils: %b %s%n", winutilsExists, winutilsPath);
134	    }
135	
136	    System.out.println("Native library checking:");
137	    System.out.printf("hadoop:  %b %s%n", nativeHadoopLoaded, hadoopLibraryName);
138	    System.out.printf("zlib:    %b %s%n", zlibLoaded, zlibLibraryName);
139	    System.out.printf("zstd  :  %b %s%n", zStdLoaded, zstdLibraryName);
140	    System.out.printf("bzip2:   %b %s%n", bzip2Loaded, bzip2LibraryName);
141	    System.out.printf("openssl: %b %s%n", openSslLoaded, openSslDetail);
142	    System.out.printf("ISA-L:   %b %s%n", isalLoaded, isalDetail);
143	    System.out.printf("PMDK:    %b %s%n", pmdkLoaded, pmdkDetail);
144	
145	    if (Shell.WINDOWS) {
146	      System.out.printf("winutils: %b %s%n", winutilsExists, winutilsPath);
147	    }
148	
149	    if ((!nativeHadoopLoaded) || (Shell.WINDOWS && (!winutilsExists)) ||
150	        (checkAll && !(zlibLoaded && bzip2Loaded
151	            && isalLoaded && zStdLoaded))) {
152	      // return 1 to indicated check failed
153	      ExitUtil.terminate(1);
154	    }
155	  }
156	}

